// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2003, "10-11", [{"author":"М. Кронгауз","question":"У Маши был велосипед, а у её брата Пети не было. Однажды Петин сосед, возвращаясь домой, увидел, что тот катается на Машином велосипеде.\n— Чей это велосипед?\n— спросил сосед.\n— Теперь мой,\n— ответил Петя.\n— Как так?\n— удивился сосед.\n— Вот так.\n— На время?\n— Навсегда.\n— Ты забрал его тайком?\n— Нет.\n— Силой?\n— Нет, Маша сама отдала.\n— Ты дал за него денег?\n— Нет.\nТогда сосед догадался, что Петя велосипед","choices":["одолжил","купил","отнял","выменял","украл."],"key":"Г","review":["Покупка, кража или обмен","Велосипед остался у Пети навсегда, сестра отдала его добровольно, денег Петя не давал.","Из предложенных действий подходит обмен: Петя выменял велосипед."]},{"author":"Е. Дмитриева","question":"Есть такой вид спорта — <em>пентатлон</em>. Догадайтесь, как он называется по-русски:","choices":["<em>зимнее двоеборье</em>","<em>троеборье</em>","<em>пятиборье</em>","<em>семиборье</em>","<em>десятиборье</em>?"],"key":"В","review":["Греческая часть названия","«Пента-» означает пять, как в названии пятиугольника «пентагон».","«-атлон» связан с состязанием. Пентатлон — пятиборье."]},{"author":"А. Богданов","question":"В каких предложениях слово <em>солдат</em> стоит во множественном числе?\n1) <em>Сегодня награждены 23 смелых солдата</em>.\n2) <em>Солдат не видит</em>.\n3) <em>Солдат не видно</em>.\n4) <em>Четыре солдата стреляют</em>.","choices":["1, 3, 4","1, 4","3","1, 2, 3, 4","3, 4."],"key":"В","review":["Числительное и форма слова","После 23 и 4 используется форма «солдата» родительного падежа единственного числа, хотя людей несколько. «Солдат не видит» начинается формой единственного числа.","«Солдат не видно» употребляет родительный множественного. Только третий пример подходит."]},{"author":"Н. Валеева","question":"Дан список глаголов: (<em>не</em>)<em>взлюбить</em>, (<em>не</em>)<em>волить</em>, (<em>не</em>)<em>годовать</em>, (<em>не</em>)<em>дождаться</em>, (<em>не</em>)<em>доумевать</em>, (<em>не</em>)<em>здоровиться</em>, (<em>не</em>)<em>истовствовать</em>, (<em>не</em>)<em>ладить</em>, (<em>не</em>)<em>сдобровать</em>, (<em>не</em>)<em>угодить</em>. В скольких случаях <em>не</em> следует написать раздельно?","choices":["во всех","в одном","в двух","в трёх","более чем в трёх."],"key":"Г","review":["Когда «не» пишется отдельно","«Дождаться», «ладить» и «угодить» существуют сами по себе. С отрицанием: «не дождаться», «не ладить», «не угодить».","Остальные глаголы в современных обычных значениях начинаются со слитного не-. Раздельных написаний три."]},{"author":"Н. Муравенко","question":"На первый взгляд кажется, что все эти сложные существительные со вторым компонентом -<em>вед</em> образованы одинаково. Но на самом деле при образовании одного из них произошли некоторые дополнительные изменения. Найдите это слово.","choices":["<em>языковед</em>","<em>литературовед</em>","<em>театровед</em>","<em>лермонтовед</em>","<em>пушкиновед</em>."],"key":"Г","review":["Столкновение частей слова","«Языковед», «литературовед», «театровед» и «пушкиновед» добавляют к первой основе соединительное о и часть -вед.","При полном соединении от «Лермонтов» получилось бы «лермонтововед». Повторившаяся часть сократилась, стало «лермонтовед»."]},{"author":"И. Иткин","question":"В названии какой из пьес А.Н. Островского имеется нарушение грамматических норм современного русского языка?","choices":["«Без вины виноватые»","«Грех да беда на кого не живёт»","«За чем пойдёшь, то и найдёшь»","«Не было ни гроша, да вдруг алтын»","«Не так живи, как хочется»."],"key":"Б","review":["Старинное управление","В названии «Грех да беда на кого не живёт» сохранена старинная пословица. В ней «на кого» связано с глаголом «жить» в уже вышедшем из употребления значении.","Сегодня о том же обычно скажут «с кем не случается беда?». Остальные названия не требуют такого старого управления."]},{"author":"И. Иткин","question":"У какого из следующих прилагательных краткая форма мужского рода образуется с отклонением от общего правила?","choices":["<em>достойный</em>","<em>спокойный</em>","<em>стройный</em>","<em>случайный</em>","<em>буйный</em>."],"key":"А","review":["Гласная в краткой форме","Краткие формы: «спокоен», «строен», «случаен» и «буен» — с е перед н.","У «достойный» краткая форма «достоин», с и. Это отклонение."]},{"author":"Е. Дмитриева","question":"<em>За деревьями не видеть леса</em> — это:","choices":["иметь узкий кругозор","быть близоруким","быть низкорослым","быть плохим лесником","проявлять внимание к мелочам в ущерб главному."],"key":"Д","review":["Детали закрывают целое","Деревья в выражении — отдельные детали, лес — общая картина.","«За деревьями не видеть леса» значит сосредоточиться на мелочах так, что не замечаешь главного."]},{"author":"И. Рудина","question":"Какой из вариантов не содержит орфографических ошибок?","choices":["<em>Вследствие обнаружения новых улик в следствии по делу об ограблении возникла новая версия, впоследствии подтвердившаяся</em>.","<em>Вследствие обнаружения новых улик вследствии по делу об ограблении возникла новая версия, впоследствии подтвердившаяся</em>.","<em>Вследствии обнаружения новых улик в следствие по делу об ограблении возникла новая версия, в последствие подтвердившаяся</em>.","<em>В следствие обнаружения новых улик в следствии по делу об ограблении возникла новая версия, в последствии подтвердившаяся</em>.","<em>В следствии обнаружения новых улик вследствие по делу об ограблении возникла новая версия, впоследствии подтвердившаяся</em>."],"key":"А","review":["Три написания рядом","«Вследствие обнаружения» — предлог со значением «из-за». «В следствии по делу» содержит обычное существительное с отдельным предлогом.","«Впоследствии» значит «позже» и пишется слитно с и на конце. Все три написания верны в варианте А."]},{"author":"Е. Муравенко","question":"Что обычно не ставят в вазу?","choices":["Ребус А","Ребус Б","Ребус В","Ребус Г","Ребус Д"],"key":"Г","review":["Что зашифровали в ребусах","В А буквы Ц и Р и перевёрнутая нота дают «нарц-ис-с». В Б из «рот» без т и «маска» с ш вместо с получается «ромашка». В В С над Н, ёж и веник дают «под-с-н-еж-ник».","В Г Н внутри Е даёт «вен», перевёрнутый кит с запятой даёт «ик». В Д И вместе с Р и «пень» без п дают «сирень». Только в Г зашифрован предмет, который обычно в вазу не ставят: веник."],"figure":{"options":[{"src":"assets/medvezhonok/2003/10-11-10-rebus-1.webp","pixelWidth":94,"pixelHeight":54,"description":"Ц над Р, зеркально отражённый нотный стан с нотой и буква С."},{"src":"assets/medvezhonok/2003/10-11-10-rebus-2.webp","pixelWidth":162,"pixelHeight":55,"description":"Рот с запятой справа и маска с заменой С на Ш."},{"src":"assets/medvezhonok/2003/10-11-10-rebus-3.webp","pixelWidth":186,"pixelHeight":73,"description":"С над Н, ёж со знаком над ним и веник с двумя запятыми слева."},{"src":"assets/medvezhonok/2003/10-11-10-rebus-4.webp","pixelWidth":125,"pixelHeight":65,"description":"Н внутри Е и перевёрнутый кит с запятой."},{"src":"assets/medvezhonok/2003/10-11-10-rebus-5.webp","pixelWidth":179,"pixelHeight":50,"description":"Буквы И и Р держатся за руки. Перед пнём стоит запятая."}]}},{"author":"Е. Дмитриева","question":"Сколько слов в этой шуточной заметке написано неправильно? <em>\nБЕСПРЕЦЕНДЕНТНЫЙ ИНЦИНДЕНТ.\n В полицейском участке индентифицировали скомпроментировавшего себя дебошира. Он оказался воспитателем детского сада. «Странная нынче конъюнктура — константировали в полиции. — Воспитатели — не наш контингент».</em>","choices":["2","3","4","5","6."],"key":"Г","review":["Пять искажённых слов","Правильно «беспрецедентный», «инцидент», «идентифицировали» и «скомпрометировавшего». В заметке в них добавлены лишние буквы или сочетания.","«Константировали» исправляем на «констатировали». «Конъюнктура» и «контингент» написаны правильно. Ошибочных слов пять."]},{"author":"Н. Валеева","question":"В каком из этих словосочетаний прилагательное имеет нулевое окончание?","choices":["<em>отчий дом</em>","<em>беличий хвост</em>","<em>колючий ёж</em>","<em>дремучий лес</em>","<em>певчий дрозд</em>."],"key":"Б","review":["Два разных «-ий»","В «беличий» -ий входит в притяжательный суффикс, родственный тому, что слышится в «беличья». Именительное окончание нулевое.","В «отчий», «колючий», «дремучий» и «певчий» этот отрезок служит окончанием. Сравни «отчий — отчего»."]},{"author":"Е. Муравенко","question":"Какое из выделенных существительных стоит в форме винительного падежа?","choices":["опасаться <strong>неприятностей</strong>","набрать <strong>грибов</strong>","встретить <strong>друга</strong>","меня интересует этот <strong>спектакль</strong>","достичь хорошего <strong>результата</strong>."],"key":"В","review":["Падеж при глаголе","«Встретить кого?» — «друга»: это винительный падеж, у одушевлённых он похож на родительный.","«Спектакль» — подлежащее, он интересует. Остальные выделенные формы родительного падежа."]},{"author":"Е. Муравенко","question":"В какой паре слова имеют ровно четыре общих звука?","choices":["<em>просить — спорить</em>","<em>дрозд — сорт</em>","<em>дрова — ведро</em>","<em>столб — болт</em>","<em>бросать — бросит</em>."],"key":"Б","review":["Сравниваем звучание, не буквы","Конец «дрозд» оглушается: [дрост]. «Сорт» произносится [сорт].","Оба слова имеют [р], [о], [с] и [т]. У «дрозд» есть ещё начальный [д]. Это пара с четырьмя общими звуками."]},{"author":"Е. Дмитриева","question":"Выражение <em>масло масляное</em> — народная насмешка над плеоназмами, то есть употреблением лишних слов, ничего не добавляющих к смыслу высказывания. Слово <em>приоритет</em> употребляется здесь в значении «первенство». В какой из этих пяти фраз нет плеоназма?","choices":["<em>На заводе хромает трудовая дисциплина</em>.","<em>Наука — наш главный приоритет</em>.","<em>Цены постоянно растут вверх</em>.","<em>Халатность инкриминируется ему в вину</em>.","<em>Да простят меня за избитую банальность!</em>"],"key":"А","review":["Где каждое слово нужно","«Трудовая дисциплина» уточняет, какая именно дисциплина хромает: на работе.","Рост уже направлен вверх, инкриминировать значит вменять в вину, а банальность — избитая мысль. Если «приоритет» означает первенство, слово «главный» повторяет этот смысл. При другом употреблении можно говорить о главном из нескольких приоритетов."],"reviewedEdition":true,"keyNote":"Уточнено значение слова «приоритет». Если приоритетов несколько, один из них может быть главным. В исходном ключе засчитывается А."},{"author":"Н. Валеева","question":"Пушкинская строчка <em>Дни поздней осени бранят обыкновенно</em> — это:","choices":["двусоставное предложение","определённо-личное предложение","неопределённо-личное предложение","безличное предложение","назывное предложение."],"key":"В","review":["Кто бранит осень","«Бранят» стоит в форме третьего лица множественного числа. Люди, которые бранят осенние дни, не названы.","«Дни» — прямое дополнение. Предложение неопределённо-личное."]},{"author":"К. Кноп","question":"Какое из этих слов написано неправильно?","choices":["<em>абсцисса</em>","<em>искусство</em>","<em>руссификация</em>","<em>глоссарий</em>","<em>ренессанс</em>."],"key":"В","review":["Одна буква «с» лишняя","В «абсцисса», «искусство», «глоссарий» и «ренессанс» удвоенные согласные стоят нормативно.","Слово «русификация» пишется с одной с. «Руссификация» — ошибочный вариант."]},{"author":"Е. Муравенко","question":"Устаревшее слово ланиты часто встречается в произведениях 19 века, например, у А. С. Пушкина:\nИ гордый взор её так томен,\nИ цвет ланит её так тёмен,\nЧто жизни мне милей она.\nЧто же такое ланиты?","choices":["глаза","брови","щёки","губы","волосы."],"key":"В","review":["Название части лица","В отрывке упоминается цвет ланит, а это цвет части лица, оттенок которой можно заметить.","Старинное «ланиты» означает «щёки». Подходит вариант В."]},{"author":"Е. Муравенко","question":"Даны пары существительных, каждая из которых включает фамилию и нарицательное существительное. В какой паре слова соотносятся не так, как в остальных?","choices":["<em>Дизель</em> (немецкий инженер) — <em>дизель</em> (вид двигателя)","<em>Ампер</em> (французский физик) — <em>ампер</em> (единица силы тока)","<em>Галифе</em> (французский генерал) — <em>галифе</em> (брюки определённого покроя)","<em>Пастернак</em> (русский поэт) — <em>пастернак</em> (корнеплод семейства зонтичных)","<em>Наган</em> (бельгийский конструктор) — <em>наган</em> (револьвер особой системы)."],"key":"Г","review":["Откуда взялись названия","Двигатель «дизель», единица «ампер», брюки «галифе» и револьвер «наган» названы по фамилиям.","Растение «пастернак» существовало как название независимо от поэта. В этой паре нарицательное не образовано из фамилии."]},{"author":"Е. Муравенко","question":"Какое из словосочетаний не может употребляться как фразеологизм?","choices":["<em>махнуть рукой</em>","<em>нечист на руку</em>","<em>вымыть руки</em>","<em>умывать руки</em>","<em>развязать кому-л. руки</em>."],"key":"В","review":["Буквальное сочетание","«Махнуть рукой», «нечист на руку», «умывать руки» и «развязать руки» употребляются в переносных значениях.","«Вымыть руки» обычно означает очистить руки водой. Здесь нет устойчивого переносного выражения."]},{"author":"Е. Муравенко","question":"В каком из перечисленных четырёх падежей ни у одного русского существительного не может быть окончания <em>-у</em>?","choices":["в родительном,","в дательном,","в винительном,","в предложном,","в каждом из четырёх перечисленных падежей у существительного может встретиться окончание <em>-у</em>."],"key":"Д","review":["Окончание «-у» в падежах","Родительный возможен в «стакан чаю», дательный — «к дому».","Винительный — «вижу сосну», предложный — «в лесу». Во всех четырёх падежах найдутся формы с -у."]},{"author":"И. Иткин","question":"Даны удвоенные согласные: <em>гг, дд, жж, мм, нн, рр, тт</em>. Какие из этих удвоенных согласных встречаются только в словах иностранного происхождения?","choices":["<em>гг, дд, жж</em>","<em>мм, нн, рр</em>","<em>гг, мм, рр</em>","<em>гг, рр, тт</em>","<em>жж, мм, тт</em>."],"key":"В","review":["Удвоения внутри русских слов","Дд есть в «поддать», жж — в «жжёт», нн — в «длинный», тт — в «оттепель».","Для гг, мм, рр обычные примеры — заимствования вроде «агглютинативный», «грамм», «терраса». Это группа В."]},{"author":"Е. Дмитриева","question":"<em>Упасть навзничь</em> — это как?","choices":["на бок","вниз головой","замертво","на спину, вверх лицом","на живот, вниз лицом."],"key":"Г","review":["Как падают навзничь","Падающий навзничь опрокидывается назад и оказывается лицом вверх.","О падении вперёд, лицом вниз, говорят «ничком». «Навзничь» — на спину."]},{"author":"Е. Муравенко","question":"Какую из этих фраз можно понять только одним способом?","choices":["<em>Ночь сменяет ясный день</em>.","<em>Роняет лес багряный свой убор</em>. (А. Пушкин)","<em>Андрей вчера сдавал экзамен по математике</em>.","<em>Как заинтересовали её картины моего друга!</em>","<em>Нина читала книгу матери.</em>"],"key":"В","review":["Что делает фразу двусмысленной","«Ночь сменяет ясный день» допускает перестановку ролей, «багряный» может относиться к лесу или убору. «Её» и «моего друга» могут по-разному распределяться по ролям, а «матери» может означать адресата или владельца книги.","Во фразе об экзамене ясно, кто сдавал экзамен, когда и по какому предмету. У неё нет таких двусмысленностей."]},{"author":"Е. Муравенко","question":"В скольких предложениях из перечисленных представлено простое глагольное сказуемое:\n1) <em>Антон не обращал внимания на советы друзей</em>.\n2) <em>Сестра вышла купить хлеба</em>.\n3) <em>Он обвёл нас вокруг пальца</em>.\n4) <em>Мы будем заниматься до обеда</em>.\n5) <em>Олег было пошёл в школу...</em>","choices":["во всех","в четырёх","в трёх","в двух","в одном."],"key":"А","review":["Пять простых сказуемых","«Не обращал внимания» и «обвёл вокруг пальца» — цельные сочетания. «Вышла» — сказуемое, а «купить» обозначает цель выхода.","«Будем заниматься» — составная форма будущего одного глагола, «пошёл» сочетается с частицей «было». Во всех пяти сказуемое простое."]},{"author":"Е. Муравенко","question":"Какие глаголы из перечисленных относятся ко 2 спряжению: 1) <em>поесть,</em> 2) <em>отбежать,</em> 3) <em>завертеться,</em> 4) <em>выстоять.</em>","choices":["2","3","2, 3","3, 4","все."],"key":"Г","review":["Как определить спряжение","«Завертеться» и «выстоять» образованы от «вертеться» и «стоять»: «вертятся», «стоят». Это окончания второго спряжения.","«Отбежать» наследует формы разноспрягаемого «бежать», а «поесть» имеет особые формы «есть». Подходят 3 и 4."]},{"author":"Е. Буторина","question":"В каких предложениях правильно расставлены знаки препинания?\n1) <em>Как только прекращался дождь и выглядывало солнце, он выбегал во двор</em>.\n2) <em>Загадочным и таинственным казался этот лес и жившие в нём сильные и смелые люди</em>.\n3) <em>А в обычные дни этот пышный подъезд осаждают убогие лица: прожектёры, искатели мест, и преклонный старик, и вдовица.</em>\n4) <em>Однако она уехала и не сказала куда</em>.\n5) <em>Я только боюсь, что если закричу, земной шар с оси сорвётся</em>.","choices":["только в 5","в 3 и 4","в 1 и 2","в 2, 3 и 5","во всех, кроме 5."],"key":"Д","review":["Когда ставится запятая","В первых четырёх предложениях запятые согласуются со строением. Например, одиночное «куда» после «не сказала» не отделяют.","В пятом нужно отделить вставленное условие: «Я только боюсь, что, если закричу, земной шар с оси сорвётся». Верны все, кроме пятого."]},{"author":"Е. Муравенко","question":"Может ли окончание оказаться перед корнем в слитно пишущемся слове?","choices":["нет","да, но только в сложных существительных","да, но только в сложных прилагательных","да, но только в сложных числительных","да, в сложных существительных, прилагательных и числительных."],"key":"Г","review":["Окончание в первой части","Обе части «пятьдесят» склоняются: «пятидесяти», «пятьюдесятью». Окончание первой части стоит перед корнем второй.","Такое устройство характерно для сложных числительных. В сложных существительных и прилагательных внутри слова обычно соединительная гласная."]},{"author":"И. Иткин","question":"Даны польские слова в принятой орфографии и в несколько упрощённой русской транскрипции и их русские соответствия:\nrybak [рыбак] <em>рыбак</em>\nmorzyła [можыла] <em>морила</em>\nrzeka [жэка] <em>река</em>\nczart [чарт] <em>чёрт</em>\ntarli [тарли] <em>тёрли</em>\norzech [ожэх] <em>орех</em>\nВ каком из следующих польских слов буквосочетание rz читается иначе, чем в остальных?","choices":["rzepa","gorzeli","burza","grzech","marzła."],"key":"Д","review":["Когда «r» и «z» раздельны","В примерах orzech и rzeka сочетание rz обозначает один звук, приблизительно [ж]. Так читаются также первые четыре ответа.","В marzła от «мёрзнуть» r и z принадлежат к разным звукам, как р и з в «мёрзла». Этот вариант исключение."]},{"author":"Е. Муравенко","question":"Какие из приведённых сложноподчинённых предложений содержат придаточные предложения времени?\n1) <em>Александр не любил, когда Горчаков переписывал его стихи, похваливая</em>. (Ю. Тынянов)\n2) <em>И он вздохнул о прежних днях, когда он жил, страстям чужой, с природой жизнию одной</em>. (М. Лермонтов)\n3) <em>Как только мы заходили за какую-нибудь вершину, шум моря замирал</em>. (В. Арсеньев)","choices":["все","1, 2","2","3","2, 3."],"key":"Г","review":["Придаточное времени","В первом примере придаточное обозначает, чего не любил Александр. Во втором поясняет, какие именно дни он вспоминает.","Только третье отвечает на «когда замирал шум моря?». «Как только…» прямо вводит время действия."]}], {"year":2003,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2003.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
